 1	/**
 2	 * Unit tests for the api.config namespace in api.js.
 3	 *
 4	 * Uses Node's built-in test runner and a lightweight fetch mock.
 5	 * Run individually with:
 6	 *   node --test gui/public/js/api.config.test.mjs
 7	 */
 8	
 9	import { test, before, afterEach } from 'node:test';
10	import assert from 'node:assert/strict';
11	
12	// ---------------------------------------------------------------------------
13	// fetch mock infrastructure
14	// ---------------------------------------------------------------------------
15	
16	/**
17	 * Captured calls made to the mocked fetch.
18	 * @type {{ method: string, url: string, body?: unknown }[]}
19	 */
20	const calls = [];
21	
22	/**
23	 * The response the next fetch call should simulate.
24	 * @type {{ status: number, body?: unknown, contentType?: string }}
25	 */
26	let nextResponse = { status: 200, body: {}, contentType: 'application/json' };
27	
28	/**
29	 * Install a global fetch mock before any test runs.
30	 * The mock records the URL, method, and body, then returns the value of `nextResponse`.
31	 */
32	before(() => {
33	    globalThis.fetch = async (url, options = {}) => {
34	        const rawBody = options.body;
35	        calls.push({
36	            method: options.method ?? 'GET',
37	            url: String(url),
38	            body: rawBody ? JSON.parse(rawBody) : undefined,
39	        });
40	
41	        const { status, body, contentType = 'application/json' } = nextResponse;
42	        const bodyText = body !== undefined ? JSON.stringify(body) : '';
43	
44	        return {
45	            status,
46	            ok: status >= 200 && status < 300,
47	            statusText: 'OK',
48	            headers: {
49	                get(name) {
50	                    if (name === 'Content-Type') return contentType;
51	                    return null;
52	                },
53	            },
54	            json() {
55	                return Promise.resolve(JSON.parse(bodyText));
56	            },
57	        };
58	    };
59	});
60	
61	/** Reset captured calls and the next-response configuration after each test. */
62	afterEach(() => {
63	    calls.length = 0;
64	    nextResponse = { status: 200, body: {}, contentType: 'application/json' };
65	});
66	
67	// ---------------------------------------------------------------------------
68	// Import the module under test
69	// Note: api.js is an ES module — import works directly in Node 18+.
70	// ---------------------------------------------------------------------------
71	
72	const { api } = await import('./api.js');
73	
74	// ---------------------------------------------------------------------------
75	// Structure tests
76	// ---------------------------------------------------------------------------
77	
78	test('api.config.polling is exported as part of the api object', () => {
79	    assert.ok(api.config, 'api.config should exist');
80	    assert.ok(api.config.polling, 'api.config.polling should exist');
81	    assert.equal(typeof api.config.polling.get, 'function', 'api.config.polling.get should be a function');
82	    assert.equal(typeof api.config.polling.set, 'function', 'api.config.polling.set should be a function');
83	});
84	
85	// ---------------------------------------------------------------------------
86	// api.config.polling.get()
87	// ---------------------------------------------------------------------------
88	
89	test('api.config.polling.get() sends GET /api/config/polling and returns the parsed response', async () => {
90	    const expected = { gitPollingIntervalSeconds: 30 };
91	    nextResponse = { status: 200, body: expected, contentType: 'application/json' };
92	
93	    const result = await api.config.polling.get();
94	
95	    assert.equal(calls.length, 1, 'exactly one fetch call expected');
96	    assert.equal(calls[0].method, 'GET');
97	    assert.equal(calls[0].url, '/api/config/polling');
98	    assert.deepEqual(result, expected);
99	});

  1	/**
  2	 * API Client for Repo Parallelizer GUI.
  3	 *
  4	 * Centralises all HTTP communication with the backend REST API.
  5	 * All methods return Promises. Non-2xx responses throw an Error whose
  6	 * message is taken from the `error` field in the JSON response body.
  7	 *
  8	 * Usage:
  9	 *   import { api } from './api.js';
 10	 *
 11	 *   const repos = await api.repositories.list();
 12	 *   const project = await api.projects.get('my-project');
 13	 */
 14	
 15	// ---------------------------------------------------------------------------
 16	// Internal HTTP helper
 17	// ---------------------------------------------------------------------------
 18	
 19	/**
 20	 * Perform a fetch request and return the parsed JSON body.
 21	 *
 22	 * For 204 No Content responses the Promise resolves with `undefined`.
 23	 * For non-2xx responses, an Error is thrown whose message comes from
 24	 * the `error` field in the JSON response body (falling back to the HTTP
 25	 * status text if the body cannot be parsed).
 26	 *
 27	 * @param {string} method - HTTP method (GET, POST, PUT, DELETE, …).
 28	 * @param {string} url    - Absolute or relative URL.
 29	 * @param {Object} [body] - Optional request body (serialised as JSON).
 30	 * @returns {Promise<*>}
 31	 */
 32	async function request(method, url, body) {
 33	    /** @type {RequestInit} */
 34	    const options = {
 35	        method,
 36	        headers: {
 37	            'Content-Type': 'application/json',
 38	            'Accept': 'application/json',
 39	        },
 40	    };
 41	
 42	    if (body !== undefined) {
 43	        options.body = JSON.stringify(body);
 44	    }
 45	
 46	    const response = await fetch(url, options);
 47	
 48	    // 204 No Content — nothing to parse.
 49	    if (response.status === 204) {
 50	        return undefined;
 51	    }
 52	
 53	    // Attempt to parse JSON for all other responses.
 54	    let json;
 55	    const contentType = response.headers.get('Content-Type') || '';
 56	    if (contentType.includes('application/json')) {
 57	        json = await response.json();
 58	    }
 59	
 60	    if (!response.ok) {
 61	        const message =
 62	            (json && json.error) ? json.error : response.statusText;
 63	        const err = new Error(message);
 64	        err.status = response.status;
 65	        throw err;
 66	    }
 67	
 68	    return json;
 69	}
