 71	// ---------------------------------------------------------------------------
 72	// Shared type definitions
 73	// ---------------------------------------------------------------------------
 74	
 75	/**
 76	 * A project object as returned by the backend REST API.
 77	 *
 78	 * The Go backend serialises struct fields using their Go-style capitalised
 79	 * names (`Id`, `Name`, `Description`, `Repositories`). Future serialiser
 80	 * changes may emit lowercase equivalents (`id`, `name`, `description`,
 81	 * `repositories`). View code **must** normalise both casings:
 82	 *
 83	 * ```js
 84	 * const id   = project.Id   || project.id   || '';
 85	 * const name = project.Name || project.name || id;
 86	 * ```
 87	 *
 88	 * @typedef {Object} ProjectResponse
 89	 * @property {string}   [Id]            - Project ID (Go-capitalised key).
 90	 * @property {string}   [id]            - Project ID (lowercase key).
 91	 * @property {string}   [Name]          - Human-readable project name (Go-capitalised key).
 92	 * @property {string}   [name]          - Human-readable project name (lowercase key).
 93	 * @property {string}   [Description]   - Optional project description (Go-capitalised key).
 94	 * @property {string}   [description]   - Optional project description (lowercase key).
 95	 * @property {Array}    [Repositories]  - Array of associated repository objects (Go-capitalised key).
 96	 * @property {Array}    [repositories]  - Array of associated repository objects (lowercase key).
 97	 */
 98	
 99	// ---------------------------------------------------------------------------
100	// API namespaces

101	test('api.config.polling.get() returns the gitPollingIntervalSeconds value', async () => {
102	    nextResponse = { status: 200, body: { gitPollingIntervalSeconds: 60 }, contentType: 'application/json' };
103	
104	    const result = await api.config.polling.get();
105	
106	    assert.equal(result.gitPollingIntervalSeconds, 60);
107	});
108	
109	test('api.config.polling.get() throws when response is not ok', async () => {
110	    nextResponse = { status: 500, body: { error: 'Internal Server Error' }, contentType: 'application/json' };
111	
112	    await assert.rejects(
113	        () => api.config.polling.get(),
114	        (err) => {
115	            assert.ok(err instanceof Error, 'should throw an Error');
116	            return true;
117	        },
118	    );
119	});
120	
121	// ---------------------------------------------------------------------------
122	// api.config.polling.set()
123	// ---------------------------------------------------------------------------
124	
125	test('api.config.polling.set(seconds) sends PUT /api/config/polling with { seconds } body', async () => {
126	    const expected = { gitPollingIntervalSeconds: 60 };
127	    nextResponse = { status: 200, body: expected, contentType: 'application/json' };
128	
129	    await api.config.polling.set(60);
130	
131	    assert.equal(calls.length, 1, 'exactly one fetch call expected');
132	    assert.equal(calls[0].method, 'PUT');
133	    assert.equal(calls[0].url, '/api/config/polling');
134	    assert.deepEqual(calls[0].body, { seconds: 60 });
135	});
136	
137	test('api.config.polling.set(seconds) returns the updated config on success', async () => {
138	    const expected = { gitPollingIntervalSeconds: 120 };
139	    nextResponse = { status: 200, body: expected, contentType: 'application/json' };
140	
141	    const result = await api.config.polling.set(120);
142	
143	    assert.deepEqual(result, expected);
144	});
145	
146	test('api.config.polling.set(seconds) throws when response is not ok', async () => {
147	    nextResponse = {
148	        status: 400,
149	        body: { error: 'Field "seconds" must be at least 10. Received: 5.' },
150	        contentType: 'application/json',
151	    };
152	
153	    await assert.rejects(
154	        () => api.config.polling.set(5),
155	        (err) => {
156	            assert.ok(err instanceof Error, 'should throw an Error');
157	            return true;
158	        },
159	    );
160	});
161	
162	test('api.config.polling.set(86400) succeeds at the maximum boundary', async () => {
163	    const expected = { gitPollingIntervalSeconds: 86400 };
164	    nextResponse = { status: 200, body: expected, contentType: 'application/json' };
165	
166	    const result = await api.config.polling.set(86400);
167	
168	    assert.equal(calls[0].body.seconds, 86400);
169	    assert.deepEqual(result, expected);
170	});
171	
