212	// api.config.notesDisplay.set()
213	// ---------------------------------------------------------------------------
214	
215	test('api.config.notesDisplay.set(data) sends PUT /api/config/notes-display with the provided data', async () => {
216	    const payload = { showEmptyNotes: false, sortOrder: 'recent' };
217	    const expected = { showEmptyNotes: false, sortOrder: 'recent' };
218	    nextResponse = { status: 200, body: expected, contentType: 'application/json' };
219	
220	    await api.config.notesDisplay.set(payload);
221	
222	    assert.equal(calls.length, 1, 'exactly one fetch call expected');
223	    assert.equal(calls[0].method, 'PUT');
224	    assert.equal(calls[0].url, '/api/config/notes-display');
225	    assert.deepEqual(calls[0].body, payload);
226	});
227	
228	test('api.config.notesDisplay.set(data) returns the updated config on success', async () => {
229	    const expected = { showEmptyNotes: true, sortOrder: 'alpha' };
230	    nextResponse = { status: 200, body: expected, contentType: 'application/json' };
231	
232	    const result = await api.config.notesDisplay.set(expected);
233	
234	    assert.deepEqual(result, expected);
235	});
236	
237	test('api.config.notesDisplay.set(data) throws when response is not ok', async () => {
238	    nextResponse = {
239	        status: 400,
240	        body: { error: 'Invalid display settings payload.' },
241	        contentType: 'application/json',
242	    };
243	
